import React, { useState, useEffect } from 'react';
import './ProjectBoard.css';
import { Plus, Minus, X, Edit2, Check, Layout, Send, ChevronLeft, ChevronRight } from 'lucide-react';
import { useParams } from 'react-router-dom';
import { auth, db } from './firebaseConfig';
import { onAuthStateChanged } from 'firebase/auth';
import { doc, getDoc, serverTimestamp } from 'firebase/firestore';
import {
    getProjectPhases,
    addProjectPhase,
    updateProjectPhase,
    deleteProjectPhase,
    updatePhasesOrder,
    getProjectById,
    getProjectTeamMembers,
    addProjectTask,
    getTasksByPhase,
    updateProjectTask,
    deleteProjectTask,
    uploadFile,
    logProjectAction,
    createNotification
} from './services/db_services';
import { sendTaskForReview } from './services/db_services';
import BottomNav from './BottomNav';
import Header from './Header';
import Swal from 'sweetalert2';


const ProjectBoard = () => {
    const projectId = localStorage.getItem('selectedProjectId');
    const [project, setProject] = useState(null);
    const [teamMembers, setTeamMembers] = useState([]);
    const [phases, setPhases] = useState([]);
    const [loading, setLoading] = useState(!!projectId);
    const [isUpdating, setIsUpdating] = useState(false);
    const [isSendingToMentor, setIsSendingToMentor] = useState(false);
    const [currentUserName, setCurrentUserName] = useState('');
    const [userRole, setUserRole] = useState(null);

    const [isAddTaskModalOpen, setIsAddTaskModalOpen] = useState(false);
    const [isViewTaskModalOpen, setIsViewTaskModalOpen] = useState(false);
    const [currentPhaseId, setCurrentPhaseId] = useState(null);
    const [currentTask, setCurrentTask] = useState(null);

    const [editingPhaseId, setEditingPhaseId] = useState(null);
    const [editPhaseTitle, setEditPhaseTitle] = useState('');

    const [newTaskName, setNewTaskName] = useState('');
    const [newTaskDescription, setNewTaskDescription] = useState('');
    const [newAssignBy, setNewAssignBy] = useState('');
    const [newAssignTo, setNewAssignTo] = useState('');
    const [newDeadline, setNewDeadline] = useState('');
    const [newStatus, setNewStatus] = useState('');
    const [newPriority, setNewPriority] = useState('');
    const [newTaskComment, setNewTaskComment] = useState('');
    const [selectedFiles, setSelectedFiles] = useState([]);
    const [uploading, setUploading] = useState(false);

    useEffect(() => {
        if (projectId) {
            fetchProjectTeamAndPhases(projectId);
        } else {
            setLoading(false);
        }
    }, [projectId]);

    // --- Deep Link / Auto-open Task from My Tasks ---
    useEffect(() => {
        const autoOpenTaskId = localStorage.getItem('autoOpenTaskId');
        const autoOpenPhaseId = localStorage.getItem('autoOpenPhaseId');

        if (!loading && phases.length > 0 && autoOpenTaskId && autoOpenPhaseId) {
            const targetPhase = phases.find(p => p.id === autoOpenPhaseId);
            if (targetPhase) {
                const targetTask = targetPhase.tasks.find(t => t.id === autoOpenTaskId);
                if (targetTask) {
                    viewTaskDetails(targetTask, targetPhase.id);
                }
            }
            // Clear items so it doesn't open again on re-renders/refresh
            localStorage.removeItem('autoOpenTaskId');
            localStorage.removeItem('autoOpenPhaseId');
        }
    }, [loading, phases]);

    useEffect(() => {
        const unsubscribe = onAuthStateChanged(auth, async (user) => {
            if (user) {
                const userDoc = await getDoc(doc(db, "users", user.uid));
                if (userDoc.exists()) {
                    const fullName = userDoc.data().fullName;
                    setCurrentUserName(fullName);
                    // Sync newAssignBy if we're in the middle of adding a task
                    if (isAddTaskModalOpen) {
                        setNewAssignBy(fullName);
                    }
                }
            }
        });
        return () => unsubscribe();
    }, [isAddTaskModalOpen]);

    const fetchProjectTeamAndPhases = async (id) => {
        setLoading(true);
        try {
            const [projData, phaseData, teamData] = await Promise.all([
                getProjectById(id),
                getProjectPhases(id),
                getProjectTeamMembers(id)
            ]);

            if (projData) setProject(projData);
            if (teamData) {
                setTeamMembers(teamData);
                const user = auth.currentUser;
                const myMember = teamData.find(m => m.uid === user?.uid);
                if (myMember) setUserRole(myMember.role);
            }

            const phasesWithTasks = await Promise.all(phaseData.map(async (p) => {
                const tasks = await getTasksByPhase(p.id);
                return {
                    id: p.id,
                    title: p.phaseName,
                    tasks: tasks || []
                };
            }));

            setPhases(phasesWithTasks);
        } catch (error) {
            console.error("Error fetching project data:", error);
        } finally {
            setLoading(false);
        }
    };

    const calculateProgress = (tasks) => {
        if (!tasks || tasks.length === 0) return 0;
        const completedCount = tasks.filter(t => t.completed).length;
        return Math.round((completedCount / tasks.length) * 100);
    };

    const isLeader = userRole === 'Leader' || userRole === 'Project Leader';
    const isMember = !isLeader && userRole !== 'Mentor' && userRole !== null;
    const isMentor = userRole === 'Mentor';

    const handleAddPhase = async () => {
        try {
            const newPhase = await addProjectPhase(projectId, 'New Phase', project?.Name || "");
            await logProjectAction(projectId, currentUserName, "Phase Added", `Added new phase "New Phase"`);
            setPhases(prev => [...prev, {
                id: newPhase.id,
                title: newPhase.phaseName,
                tasks: []
            }]);
        } catch (error) {
            console.error("Error adding phase:", error);
            Swal.fire({
                title: 'Error',
                text: 'Failed to add phase. Please try again.',
                icon: 'error',
                confirmButtonColor: '#1a4d8c'
            });
        }

    };

    const handleRemovePhase = async (phaseId) => {
        Swal.fire({
            title: 'Are you sure?',
            text: "Are you sure you want to remove this phase?",
            icon: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#1a4d8c',
            cancelButtonColor: '#d33',
            confirmButtonText: 'Yes, remove it!'
        }).then(async (result) => {
            if (result.isConfirmed) {
                try {
                    const phaseName = phases.find(p => p.id === phaseId)?.title || "Unknown Phase";
                    await deleteProjectPhase(phaseId);
                    await logProjectAction(projectId, currentUserName, "Phase Removed", `Removed phase "${phaseName}"`);
                    setPhases(prev => prev.filter(p => p.id !== phaseId));
                    Swal.fire({
                        title: 'Removed!',
                        text: 'The phase has been removed.',
                        icon: 'success',
                        timer: 1500,
                        showConfirmButton: false
                    });
                } catch (error) {
                    console.error("Error removing phase:", error);
                    Swal.fire({
                        title: 'Error',
                        text: 'Failed to remove phase.',
                        icon: 'error',
                        confirmButtonColor: '#1a4d8c'
                    });
                }
            }
        });
    };


    const startEditing = (phaseId, currentTitle) => {
        setEditingPhaseId(phaseId);
        setEditPhaseTitle(currentTitle);
    };

    const saveRename = async (phaseId) => {
        if (!editPhaseTitle.trim()) return;
        try {
            await updateProjectPhase(phaseId, { phaseName: editPhaseTitle });
            setPhases(prev => prev.map(p => p.id === phaseId ? { ...p, title: editPhaseTitle } : p));
            setEditingPhaseId(null);
        } catch (error) {
            console.error("Error renaming phase:", error);
            Swal.fire({
                title: 'Error',
                text: 'Failed to rename phase.',
                icon: 'error',
                confirmButtonColor: '#1a4d8c'
            });
        }

    };

    const cancelEditing = () => {
        setEditingPhaseId(null);
        setEditPhaseTitle('');
    };

    const handleMovePhase = async (phaseId, direction) => {
        const index = phases.findIndex(p => p.id === phaseId);
        if (index === -1) return;

        const newIndex = direction === 'left' ? index - 1 : index + 1;
        if (newIndex < 0 || newIndex >= phases.length) return;

        const newPhases = [...phases];
        const [movedPhase] = newPhases.splice(index, 1);
        newPhases.splice(newIndex, 0, movedPhase);

        // Update local state immediately for UX
        setPhases(newPhases);

        try {
            // Prepare the order update for DB
            const orderUpdates = newPhases.map((p, i) => ({ id: p.id, order: i }));
            await updatePhasesOrder(orderUpdates);
        } catch (error) {
            console.error("Error updating phases order:", error);
            // Optionally revert local state on error
            // fetchProjectTeamAndPhases(projectId); 
        }
    };

    const handleResetBoard = () => {
        Swal.fire({
            title: 'Reset Board?',
            text: "Are you sure you want to reset the board? This will clear all phases.",
            icon: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#1a4d8c',
            cancelButtonColor: '#d33',
            confirmButtonText: 'Yes, reset it!'
        }).then((result) => {
            if (result.isConfirmed) {
                setPhases([]);
                Swal.fire({
                    title: 'Reset Complete',
                    text: 'The board has been cleared.',
                    icon: 'success',
                    timer: 1500,
                    showConfirmButton: false
                });
            }
        });
    };


    const openAddTaskModal = (phaseId) => {
        setCurrentPhaseId(phaseId);
        setNewTaskName('');
        setNewTaskDescription('');
        setNewAssignBy(currentUserName || '');
        setNewAssignTo('');
        setNewDeadline('');
        setNewStatus('In Progress');
        setNewPriority('Medium');
        setNewTaskComment('');
        setSelectedFiles([]);
        setIsAddTaskModalOpen(true);
    };

    const handleAddTask = async (e) => {
        e.preventDefault();
        if (!newTaskName.trim()) return;

        setIsUpdating(true);
        try {
            const taskData = {
                name: newTaskName,
                description: newTaskDescription,
                assignBy: newAssignBy,
                assignTo: newAssignTo,
                deadline: newDeadline,
                status: newStatus,
                priority: newPriority,
                taskComment: newTaskComment,
                phaseId: currentPhaseId,
                projectName: project?.Name || "Project",
                completed: false,
                reviewStatus: null,
                media: { files: [] }
            };


            const taskId = await addProjectTask(taskData);

            let logDetails = `Added task "${taskData.name}"`;
            if (taskData.assignTo) {
                logDetails += ` and assigned to ${taskData.assignTo}`;
                
                // NOTIFICATION: New Assignment
                const assignedMember = teamMembers.find(m => m.fullName === taskData.assignTo);
                if (assignedMember && assignedMember.uid !== auth.currentUser?.uid) {
                    await createNotification(
                        assignedMember.uid,
                        "New Task Assigned",
                        `You have been assigned a new task: "${taskData.name}" by ${currentUserName}`,
                        "new_assignment",
                        { projectId, taskId }
                    );
                }
            }
            await logProjectAction(projectId, currentUserName, "Task Added", logDetails);

            const newTask = { id: taskId, ...taskData };
            setPhases(prev => prev.map(p => {
                if (p.id === currentPhaseId) {
                    return { ...p, tasks: [...p.tasks, newTask] };
                }
                return p;
            }));
            setIsAddTaskModalOpen(false);
            Swal.fire({
                title: 'Success!',
                text: 'Task added successfully!',
                icon: 'success',
                timer: 1500,
                showConfirmButton: false
            });
        } catch (error) {
            console.error("Error adding task:", error);
            Swal.fire({
                title: 'Error',
                text: 'Failed to add task.',
                icon: 'error',
                confirmButtonColor: '#1a4d8c'
            });
        } finally {

            setIsUpdating(false);
        }
    };

    const toggleTaskCompletion = async (e, phaseId, taskId) => {
        e.stopPropagation();
        const currentPhase = phases.find(p => p.id === phaseId);
        const task = currentPhase.tasks.find(t => t.id === taskId);

        // Permission check: Only assignee or leader can toggle
        const canToggle = isLeader || task.assignTo === currentUserName;

        if (!canToggle) {
            Swal.fire({
                title: 'Permission Denied',
                text: 'Only the assigned member or the Project Leader can mark this task as complete.',
                icon: 'info',
                confirmButtonColor: '#1a4d8c'
            });
            return;
        }

        const newCompleted = !task.completed;

        try {
            await updateProjectTask(taskId, { completed: newCompleted });
            await logProjectAction(projectId, currentUserName, "Task Status Changed", `Marked task "${task.name}" as ${newCompleted ? 'Complete' : 'Incomplete'}`);
            setPhases(prev => prev.map(p => {
                if (p.id === phaseId) {
                    return {
                        ...p,
                        tasks: p.tasks.map(t => t.id === taskId ? { ...t, completed: newCompleted } : t)
                    };
                }
                return p;
            }));
        } catch (error) {
            console.error("Error toggling task completion:", error);
        }
    };

    const viewTaskDetails = (task, phaseId) => {
        // Only reset selectedFiles if we're switching to a different task
        if (!currentTask || currentTask.id !== task.id) {
            setSelectedFiles([]);
        }
        setUploading(false);
        setCurrentTask(task);
        setCurrentPhaseId(phaseId);
        setNewTaskName(task.name);
        setNewTaskDescription(task.description);
        setNewAssignBy(task.assignBy || currentUserName || '');
        setNewAssignTo(task.assignTo || '');
        setNewDeadline(task.deadline || '');
        setNewStatus(task.status || '');
        setNewPriority(task.priority || '');
        setNewTaskComment(task.taskComment || '');
        setIsViewTaskModalOpen(true);
    };

    const handleSaveTask = async (e) => {
        e.preventDefault();
        setIsUpdating(true);

        try {
            const updates = {
                name: newTaskName,
                description: newTaskDescription,
                assignBy: newAssignBy,
                assignTo: newAssignTo,
                deadline: newDeadline,
                status: newStatus,
                priority: newPriority,
                taskComment: newTaskComment,
                media: currentTask.media || { files: [] }
            };

            // Handle additional file uploads if any
            if (selectedFiles.length > 0) {
                setUploading(true);
                const uploadPromises = selectedFiles.map(file => {
                    const filePath = `tasks/${projectId}/${Date.now()}_${file.name}`;
                    return uploadFile(file, filePath).then(url => ({
                        name: file.name,
                        url: url,
                        path: filePath
                    }));
                });

                const uploadedFiles = await Promise.all(uploadPromises);
                const existingFiles = currentTask.media?.files || [];
                updates.media = { files: [...existingFiles, ...uploadedFiles] };
            }

            await updateProjectTask(currentTask.id, updates);

            let logDetails = `Updated task "${newTaskName}"`;
            let notifyNewAssignee = false;

            if (currentTask.assignTo !== newAssignTo && newAssignTo) {
                logDetails += ` and assigned it to ${newAssignTo}`;
                notifyNewAssignee = true;
            } else if (currentTask.assignTo !== newAssignTo && !newAssignTo) {
                logDetails += ` and removed assignee`;
            }
            await logProjectAction(projectId, currentUserName, "Task Updated", logDetails);

            if (notifyNewAssignee) {
                const assignedMember = teamMembers.find(m => m.fullName === newAssignTo);
                if (assignedMember && assignedMember.uid !== auth.currentUser?.uid) {
                    await createNotification(
                        assignedMember.uid,
                        "Task Reassigned",
                        `You have been assigned the task: "${newTaskName}" by ${currentUserName}`,
                        "new_assignment",
                        { projectId, taskId: currentTask.id }
                    );
                }
            }

            setPhases(prev => prev.map(p => {
                if (p.id === currentPhaseId) {
                    return {
                        ...p,
                        tasks: p.tasks.map(t => t.id === currentTask.id ? { ...t, ...updates } : t)
                    };
                }
                return p;
            }));
            setIsViewTaskModalOpen(false);
            setSelectedFiles([]);
            Swal.fire({
                title: 'Updated!',
                text: 'Task updated successfully!',
                icon: 'success',
                timer: 1500,
                showConfirmButton: false
            });
        } catch (error) {
            console.error("Error updating task:", error);
            Swal.fire({
                title: 'Error',
                text: error.message || 'Failed to update task.',
                icon: 'error',
                confirmButtonColor: '#1a4d8c'
            });
        } finally {
            setUploading(false);
            setIsUpdating(false);
        }
    };

    const handleValidateTask = async (e) => {
        e.preventDefault();
        if (!currentTask) return;

        // Check if a mentor is added to the project
        const hasMentor = teamMembers.some(member => member.role === 'Mentor');
        if (!hasMentor) {
            Swal.fire({
                title: 'Mentor Not Found',
                text: 'A mentor is not yet added in the project for validation. Please add a mentor before validating tasks.',
                icon: 'warning',
                confirmButtonColor: '#1a4d8c'
            });
            return;
        }

        setIsSendingToMentor(true);

        try {
            const updates = {
                name: newTaskName,
                description: newTaskDescription,
                assignBy: newAssignBy,
                assignTo: newAssignTo,
                deadline: newDeadline,
                status: newStatus,
                priority: newPriority,
                taskComment: newTaskComment,
                reviewStatus: 'pending',
                updatedAt: serverTimestamp()
            };

            // Handle additional file uploads if any
            if (selectedFiles.length > 0) {
                setUploading(true);
                const uploadPromises = selectedFiles.map(file => {
                    const filePath = `tasks/${projectId}/${Date.now()}_${file.name}`;
                    return uploadFile(file, filePath).then(url => ({
                        name: file.name,
                        url: url,
                        path: filePath
                    }));
                });

                const uploadedFiles = await Promise.all(uploadPromises);
                const existingFiles = currentTask.media?.files || [];
                updates.media = { files: [...existingFiles, ...uploadedFiles] };
            } else {
                updates.media = currentTask.media || { files: [] };
            }

            const taskUpdates = { ...currentTask, ...updates };

            console.log("Updating task in Firestore...");
            await updateProjectTask(currentTask.id, updates);

            console.log("Submitting to mentor review...");
            await sendTaskForReview(taskUpdates, projectId);

            // Log the validation request
            await logProjectAction(projectId, currentUserName, "Task Sent for Validation", `Sent task "${newTaskName}" to mentor for review`);

            // NOTIFICATION: Alert the Mentor(s)
            const mentors = teamMembers.filter(m => m.role === 'Mentor');
            for (const mentor of mentors) {
                if (mentor.uid !== auth.currentUser?.uid) {
                    await createNotification(
                        mentor.uid,
                        "Task Ready for Review",
                        `${currentUserName} has submitted the task "${newTaskName}" for validation.`,
                        "task_validation",
                        { projectId, taskId: currentTask.id }
                    );
                }
            }

            setPhases(prev => prev.map(p => {
                if (p.id === currentPhaseId) {
                    return {
                        ...p,
                        tasks: p.tasks.map(t =>
                            t.id === currentTask.id
                                ? { ...t, ...taskUpdates }
                                : t
                        )
                    };
                }
                return p;
            }));

            setIsViewTaskModalOpen(false);
            setSelectedFiles([]);
            Swal.fire({
                title: 'Sent!',
                text: 'Task sent to mentor for validation!',
                icon: 'success',
                timer: 2000,
                showConfirmButton: false
            });
        } catch (error) {
            console.error("Error sending task for review:", error);
            Swal.fire({
                title: 'Error',
                text: error.message || 'Failed to send task for review.',
                icon: 'error',
                confirmButtonColor: '#1a4d8c'
            });
        } finally {
            setIsSendingToMentor(false);
            setUploading(false);
        }
    };

    const handleDeleteTask = async () => {
        Swal.fire({
            title: 'Delete Task?',
            text: "Are you sure you want to delete this task?",
            icon: 'warning',
            showCancelButton: true,
            confirmButtonColor: '#1a4d8c',
            cancelButtonColor: '#d33',
            confirmButtonText: 'Yes, delete it!'
        }).then(async (result) => {
            if (result.isConfirmed) {
                try {
                    await deleteProjectTask(currentTask.id);
                    await logProjectAction(projectId, currentUserName, "Task Deleted", `Deleted task "${currentTask.name}"`);
                    setPhases(prev => prev.map(p => {
                        if (p.id === currentPhaseId) {
                            return {
                                ...p,
                                tasks: p.tasks.filter(t => t.id !== currentTask.id)
                            };
                        }
                        return p;
                    }));
                    setIsViewTaskModalOpen(false);
                    Swal.fire({
                        title: 'Deleted!',
                        text: 'The task has been deleted.',
                        icon: 'success',
                        timer: 1500,
                        showConfirmButton: false
                    });
                } catch (error) {
                    console.error("Error deleting task:", error);
                    Swal.fire({
                        title: 'Error',
                        text: 'Failed to delete task.',
                        icon: 'error',
                        confirmButtonColor: '#1a4d8c'
                    });
                }
            }
        });
    };


    const isTaskAssignedToMe = currentTask?.assignTo === currentUserName;
    const canValidate = ((isMember && isTaskAssignedToMe) || isLeader) && currentTask?.priority === 'High';

    return (
        <div className="project-board-container">
            <Header />

            {loading ? (
                <div className="d-flex justify-content-center align-items-center" style={{ height: '70vh' }}>
                    <div className="spinner-border text-primary" role="status">
                        <span className="visually-hidden">Loading phases...</span>
                    </div>
                </div>
            ) : !projectId ? (
                <div className="no-phases-container d-flex flex-column align-items-center justify-content-center" style={{ height: '70vh' }}>
                    <Layout size={80} className="text-muted mb-4 opacity-25" />
                    <h3 className="text-muted">No project selected</h3>
                    <p className="text-muted">Select a project from the home page to view its board.</p>
                </div>
            ) : (
                <>
                    <div className="board-header shadow-sm">
                        <div className="header-left">
                            <div className="project-titles">
                                <h2 className="m-0 text-primary">{project?.Name || "Project Board"}</h2>
                                <div className="project-meta-pills">
                                    {project?.category && <span className="meta-pill category">{project.category}</span>}
                                    {project?.department && <span className="meta-pill department">{project.department}</span>}
                                </div>
                            </div>
                        </div>
                        <div className="header-right">
                            <div className="date-range-info">
                                <div className="date-item">
                                    <span className="date-label">Start Date</span>
                                    <span className="date-value">{project?.startDate || 'N/A'}</span>
                                </div>
                                <div className="date-separator"></div>
                                <div className="date-item">
                                    <span className="date-label">End Date</span>
                                    <span className="date-value">{project?.endDate || 'N/A'}</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    <div className="board-wrapper shadow-sm">
                        {phases.length === 0 ? (
                            <div className="no-phases-inner d-flex flex-column align-items-center justify-content-center py-5">
                                <h4 className="text-muted">No phases found</h4>
                                <p className="text-muted">Start by adding your first project phase below.</p>
                            </div>
                        ) : (
                            <div className="board-columns">
                                {phases.map((phase, index) => (
                                    <div key={phase.id} className="board-column">
                                        <div className="column-header">
                                            {editingPhaseId === phase.id ? (
                                                <div className="edit-phase-input-group">
                                                    <input
                                                        type="text"
                                                        className="edit-phase-input"
                                                        value={editPhaseTitle}
                                                        onChange={(e) => setEditPhaseTitle(e.target.value)}
                                                        onKeyDown={(e) => {
                                                            if (e.key === 'Enter') saveRename(phase.id);
                                                            if (e.key === 'Escape') cancelEditing();
                                                        }}
                                                        autoFocus
                                                    />
                                                    <Check size={14} className="cursor-pointer" onClick={() => saveRename(phase.id)} />
                                                </div>
                                            ) : (
                                                <>
                                                    <h6>{phase.title}</h6>
                                                    <div className="header-actions">
                                                        {isLeader && (
                                                            <>
                                                                <button
                                                                    className="move-phase-btn"
                                                                    onClick={() => handleMovePhase(phase.id, 'left')}
                                                                    disabled={index === 0}
                                                                    title="Move Left"
                                                                >
                                                                    <ChevronLeft size={14} />
                                                                </button>
                                                                <button
                                                                    className="move-phase-btn"
                                                                    onClick={() => handleMovePhase(phase.id, 'right')}
                                                                    disabled={index === phases.length - 1}
                                                                    title="Move Right"
                                                                >
                                                                    <ChevronRight size={14} />
                                                                </button>
                                                                <Edit2 size={14} className="cursor-pointer" onClick={() => startEditing(phase.id, phase.title)} />
                                                                <Minus size={14} className="cursor-pointer" onClick={() => handleRemovePhase(phase.id)} />
                                                            </>
                                                        )}
                                                    </div>
                                                </>
                                            )}
                                        </div>
                                        <div className="column-body">
                                            {isLeader && (
                                                <button className="add-task-btn" onClick={() => openAddTaskModal(phase.id)}>
                                                    <Plus size={14} /> Add task
                                                </button>
                                            )}
                                            {(() => {
                                                const priorityWeight = { 'High': 3, 'Medium': 2, 'Low': 1 };
                                                return [...phase.tasks]
                                                    .sort((a, b) => (priorityWeight[b.priority] || 0) - (priorityWeight[a.priority] || 0))
                                                    .map((task) => (
                                                        <div
                                                            key={task.id}
                                                            className={`task-item ${task.completed ? 'completed' : ''} ${task.reviewStatus === 'pending' ? 'review-pending' : ''} ${task.reviewStatus === 'reviewed' ? 'review-done' : ''} ${task.reviewStatus === 'changes_requested' ? 'review-changes' : ''}`}
                                                            onClick={() => viewTaskDetails(task, phase.id)}
                                                        >
                                                            <span>{task.name}</span>
                                                            <div className="task-badges">
                                                                {task.reviewStatus === 'pending' && <span className="review-badge pending">⏳ Pending Review</span>}
                                                                {task.reviewStatus === 'reviewed' && <span className="review-badge reviewed">✅ Reviewed</span>}
                                                                {task.reviewStatus === 'changes_requested' && <span className="review-badge changes">🔄 Changes Needed</span>}
                                                            </div>
                                                            <div className="status-circle" onClick={(e) => toggleTaskCompletion(e, phase.id, task.id)}></div>
                                                        </div>
                                                    ));
                                            })()}
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}

                        <div className="add-phase-container">
                            {isLeader && (
                                <>
                                    <button className="btn-reset-board" onClick={handleResetBoard}>Reset Board</button>
                                    <button className="btn-add-phase" onClick={handleAddPhase}><Plus size={18} /> Add Phase</button>
                                </>
                            )}
                        </div>
                    </div>
                </>
            )}

            <BottomNav />

            {/* ── Add Task Modal ── */}
            {isAddTaskModalOpen && (
                <div className="modal-overlay">
                    <div className="add-task-modal-content">
                        <div className="add-task-modal-header"><span>Add new task</span></div>
                        <form onSubmit={handleAddTask} className="add-task-form">
                            <div className="add-task-modal-body">

                                <div className="modal-grid-layout">
                                    {/* Column 1: Title + Description */}
                                    <div className="grid-column">
                                        <div className="form-field">
                                            <label>Title <span className="required-star">*</span></label>
                                            <input type="text" value={newTaskName} onChange={(e) => setNewTaskName(e.target.value)} required autoFocus />
                                        </div>
                                        <div className="form-field">
                                            <label>Description</label>
                                            <textarea
                                                value={newTaskDescription}
                                                onChange={(e) => setNewTaskDescription(e.target.value)}
                                            ></textarea>
                                        </div>
                                    </div>

                                    {/* Column 2: Assign by + Deadline + Priority */}
                                    <div className="grid-column">
                                        <div className="form-field">
                                            <label>Assign by</label>
                                            <input type="text" value={newAssignBy} readOnly className="bg-light" style={{ border: '1px solid #eef0f2' }} />
                                        </div>
                                        <div className="form-field">
                                            <label>Deadline</label>
                                            <input type="date" value={newDeadline} onChange={(e) => setNewDeadline(e.target.value)} />
                                        </div>
                                        <div className="form-field">
                                            <label>Priority <span className="required-star">*</span></label>
                                            <select value={newPriority} onChange={(e) => setNewPriority(e.target.value)} required>
                                                <option value=""></option>
                                                <option value="Low">Low</option>
                                                <option value="Medium">Medium</option>
                                                <option value="High">High</option>
                                            </select>
                                        </div>
                                    </div>

                                    {/* Column 3: Assign to + Status */}
                                    <div className="grid-column">
                                        <div className="form-field">
                                            <label>Assign to</label>
                                            <select value={newAssignTo} onChange={(e) => setNewAssignTo(e.target.value)} required>
                                                <option value="">Select Member</option>
                                                {teamMembers.map(member => (
                                                    <option key={member.uid} value={member.fullName}>
                                                        {member.fullName} ({member.role})
                                                    </option>
                                                ))}
                                            </select>
                                        </div>
                                        <div className="form-field">
                                            <label>Status <span className="required-star">*</span></label>
                                            <select value={newStatus} onChange={(e) => setNewStatus(e.target.value)}>
                                                <option value=""></option>
                                                <option value="To Do">To Do</option>
                                                <option value="In Progress">In Progress</option>
                                                <option value="Done">Done</option>
                                            </select>
                                        </div>
                                    </div>
                                </div>

                            </div>
                            <div className="add-task-modal-footer">
                                <button type="submit" className="create-task-btn" disabled={isUpdating || uploading}>
                                    {isUpdating ? <><span className="spinner-border-custom"></span> Creating...</> : "Create task"}
                                </button>
                            </div>
                        </form>
                        <div className="modal-close-icon" onClick={() => setIsAddTaskModalOpen(false)}><X size={20} /></div>
                    </div>
                </div>
            )}

            {/* ── View / Edit Task Modal ── */}
            {isViewTaskModalOpen && currentTask && (
                <div className="modal-overlay">
                    <div className="add-task-modal-content">
                        <div className="add-task-modal-header"><span>Edit task</span></div>
                        <form onSubmit={handleSaveTask} className="add-task-form">
                            <div className="add-task-modal-body">

                                <div className="modal-grid-layout">
                                    {/* Column 1: Title + Description */}
                                    <div className="grid-column">
                                        <div className="form-field">
                                            <label>Title <span className="required-star">*</span></label>
                                            <input type="text" value={newTaskName} onChange={(e) => setNewTaskName(e.target.value)} required autoFocus readOnly={isMentor || (isMember && currentTask.reviewStatus === 'reviewed')} />
                                        </div>
                                        <div className="form-field">
                                            <label>Description</label>
                                            <textarea
                                                value={newTaskDescription}
                                                onChange={(e) => setNewTaskDescription(e.target.value)}
                                                readOnly={isMentor || (isMember && currentTask.reviewStatus === 'reviewed')}
                                            ></textarea>
                                        </div>
                                    </div>

                                    {/* Column 2: Assign by + Deadline + Priority */}
                                    <div className="grid-column">
                                        <div className="form-field">
                                            <label>Assign by</label>
                                            <input type="text" value={newAssignBy} readOnly className="bg-light" style={{ border: '1px solid #eef0f2' }} />
                                        </div>
                                        <div className="form-field">
                                            <label>Deadline</label>
                                            <input type="date" value={newDeadline} onChange={(e) => setNewDeadline(e.target.value)} readOnly={isMentor || isMember || (isMember && currentTask.reviewStatus === 'reviewed')} />
                                        </div>
                                        <div className="form-field">
                                            <label>Priority <span className="required-star">*</span></label>
                                            <select value={newPriority} onChange={(e) => setNewPriority(e.target.value)} required disabled={isMentor || isMember || (isMember && currentTask.reviewStatus === 'reviewed')}>
                                                <option value=""></option>
                                                <option value="Low">Low</option>
                                                <option value="Medium">Medium</option>
                                                <option value="High">High</option>
                                            </select>
                                        </div>
                                    </div>

                                    {/* Column 3: Assign to + Status */}
                                    <div className="grid-column">
                                        <div className="form-field">
                                            <label>Assign to</label>
                                            <select value={newAssignTo} onChange={(e) => setNewAssignTo(e.target.value)} required disabled={isMentor || (isMember && currentTask.reviewStatus === 'reviewed')}>
                                                <option value="">Select Member</option>
                                                {teamMembers.map(member => (
                                                    <option key={member.uid} value={member.fullName}>
                                                        {member.fullName} ({member.role})
                                                    </option>
                                                ))}
                                            </select>
                                        </div>
                                        <div className="form-field">
                                            <label>Status <span className="required-star">*</span></label>
                                            <select value={newStatus} onChange={(e) => setNewStatus(e.target.value)} required disabled={isMentor || (isMember && currentTask.reviewStatus === 'reviewed')}>
                                                <option value=""></option>
                                                <option value="To Do">To Do</option>
                                                <option value="In Progress">In Progress</option>
                                                <option value="Done">Done</option>
                                            </select>
                                        </div>
                                    </div>
                                </div>

                                {/* Row 3: Review Status + Mentor Feedback side by side */}
                                {currentTask.reviewStatus && (
                                    <div className="review-mentor-row mt-4">
                                        <div className="form-field">
                                            <label>Review Status</label>
                                            <div className={`review-status-pill ${currentTask.reviewStatus}`}>
                                                {currentTask.reviewStatus === 'pending' && '⏳ Awaiting Mentor Review'}
                                                {currentTask.reviewStatus === 'reviewed' && '✅ Reviewed by Mentor'}
                                                {currentTask.reviewStatus === 'changes_requested' && '🔄 Changes Requested'}
                                            </div>
                                        </div>

                                        {currentTask.reviewStatus === 'changes_requested' && currentTask.mentorComment && (
                                            <div className="form-field">
                                                <label style={{ color: '#dc3545' }}>🔄 Mentor Feedback</label>
                                                <textarea
                                                    value={currentTask.mentorComment}
                                                    readOnly
                                                    rows="3"
                                                    style={{ backgroundColor: '#fff3f3', border: '1px solid #dc3545', borderRadius: '8px', padding: '8px', resize: 'none', width: '100%' }}
                                                />
                                            </div>
                                        )}
                                    </div>
                                )}

                                {/* File Attachments Section */}
                                <div className="form-field mt-3">
                                    <label>Attachments</label>

                                    {/* Existing Files */}
                                    {currentTask.media?.files && currentTask.media.files.length > 0 && (
                                        <div className="existing-files-grid mb-3">
                                            {currentTask.media.files.map((file, i) => (
                                                <div key={i} className="file-attachment-card">
                                                    <div className="file-info">
                                                        <span className="file-name" title={file.name}>{file.name}</span>
                                                    </div>
                                                    <a href={file.url} target="_blank" rel="noopener noreferrer" className="view-file-link">View</a>
                                                </div>
                                            ))}
                                        </div>
                                    )}

                                    {/* Upload New Files */}
                                    {!(isMentor || (isMember && currentTask.reviewStatus === 'reviewed')) && (
                                        <>
                                            <input
                                                type="file"
                                                multiple
                                                onChange={(e) => setSelectedFiles(Array.from(e.target.files))}
                                                className="form-control"
                                            />
                                            {selectedFiles.length > 0 && (
                                                <div className="selected-files-list mt-2">
                                                    {selectedFiles.map((file, i) => (
                                                        <div key={i} className="selected-file-item text-muted small">
                                                            📎 {file.name} ({(file.size / 1024).toFixed(1)} KB)
                                                        </div>
                                                    ))}
                                                </div>
                                            )}
                                        </>
                                    )}
                                </div>

                                {/* Comments / External Links */}
                                <div className="form-field mt-3">
                                    <label>Student Comments / Links</label>
                                    <textarea
                                        value={newTaskComment}
                                        onChange={(e) => setNewTaskComment(e.target.value)}
                                        readOnly={isMentor || (isMember && currentTask.reviewStatus === 'reviewed')}
                                        placeholder="Add comments or links to external files (e.g., Google Drive, GitHub)..."
                                        rows="3"
                                        style={{ width: '100%', resize: 'vertical' }}
                                    ></textarea>
                                </div>

                            </div>

                            <div className="add-task-modal-footer">
                                {isLeader && (
                                    <button type="button" className="delete-task-btn" onClick={handleDeleteTask}>
                                        Delete Task
                                    </button>
                                )}

                                {canValidate && currentTask.reviewStatus !== 'pending' && currentTask.reviewStatus !== 'reviewed' && (
                                    <button
                                        type="button"
                                        className="validate-task-btn"
                                        onClick={handleValidateTask}
                                        disabled={isSendingToMentor || uploading}
                                        title="Send this task to the mentor for review"
                                    >
                                        {isSendingToMentor || uploading
                                            ? <><span className="spinner-border-custom"></span> {uploading ? "Uploading..." : "Sending..."}</>
                                            : <><Send size={14} /> Validate Task</>
                                        }
                                    </button>
                                )}

                                {!isMentor && !(isMember && currentTask.reviewStatus === 'reviewed') && (
                                    <button type="submit" className="create-task-btn" disabled={isUpdating || uploading}>
                                        {isUpdating || uploading ? <><span className="spinner-border-custom"></span> {uploading ? "Uploading..." : "Saving..."}</> : "Save Changes"}
                                    </button>
                                )}
                            </div>
                        </form>
                        <div className="modal-close-icon" onClick={() => {
                            setIsViewTaskModalOpen(false);
                            setSelectedFiles([]);
                        }}><X size={20} /></div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ProjectBoard;