import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { Search, Bell, User as UserIcon, History } from 'lucide-react';
import Swal from 'sweetalert2';
import { auth, db } from './firebaseConfig';

import { doc, collection, query, where, onSnapshot, orderBy, limit } from 'firebase/firestore';
import { onAuthStateChanged } from 'firebase/auth';
import { getUserRoleInProject, getUserProjects } from './services/db_services';
import './Header.css';

const Header = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const [userData, setUserData] = useState({ fullName: 'User', role: 'Member', email: '', profilePicture: '' });
    const [projectRole, setProjectRole] = useState(null);
    const [isProfilePopupOpen, setIsProfilePopupOpen] = useState(false);
    const [inviteCount, setInviteCount] = useState(0);
    const [unreadCount, setUnreadCount] = useState(0);
    const [notificationCount, setNotificationCount] = useState(0);
    const [latestNews, setLatestNews] = useState(null);
    const [allNews, setAllNews] = useState([]);
    const [newsIndex, setNewsIndex] = useState(0);
    const [isNewsModalOpen, setIsNewsModalOpen] = useState(false);
    const [userProjects, setUserProjects] = useState([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [filteredProjects, setFilteredProjects] = useState([]);
    const [isSearchDropdownOpen, setIsSearchDropdownOpen] = useState(false);

    const [currentUser, setCurrentUser] = useState(null);
    const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
    const [projectLogs, setProjectLogs] = useState([]);

    // Auth state listener
    useEffect(() => {
        const unsubscribeAuth = onAuthStateChanged(auth, (user) => {
            setCurrentUser(user);
        });
        return () => unsubscribeAuth();
    }, []);

    // User profile listener
    useEffect(() => {
        if (!currentUser) return;

        const userDocRef = doc(db, "users", currentUser.uid);
        const unsubscribeUser = onSnapshot(userDocRef, (docSnap) => {
            if (docSnap.exists()) {
                setUserData({ ...docSnap.data(), email: currentUser.email });
            }
        });
        return () => unsubscribeUser();
    }, [currentUser]);

    // Project role, invitations and news listener
    useEffect(() => {
        if (!currentUser) return;

        // Define project-specific routes for news visibility gating
        const PROJECT_ROUTES = ['/project-board', '/mentorDashboard', '/Progress', '/Reviewtask'];
        const isProjectRoute = PROJECT_ROUTES.includes(location.pathname);

        // 1. GLOBAL LISTENERS (Always run when logged in)

        // Fetch all projects for global search
        getUserProjects(currentUser.uid).then(setUserProjects);

        // Real-time listener for invitations
        const invQuery = query(
            collection(db, "invitations"),
            where("recipientUid", "==", currentUser.uid),
            where("status", "==", "pending")
        );
        const unsubscribeInvites = onSnapshot(invQuery, (snapshot) => {
            setInviteCount(snapshot.size);
        });

        // Real-time listener for general unread notifications
        const notificationQuery = query(
            collection(db, "notifications"),
            where("recipientUid", "==", currentUser.uid),
            where("read", "==", false)
        );
        const unsubscribeNotifs = onSnapshot(notificationQuery, (snapshot) => {
            setUnreadCount(snapshot.size);
        });

        // 2. PROJECT-SPECIFIC LISTENERS (Run only if a project is selected AND on a project route)
        const selectedProjectId = localStorage.getItem('selectedProjectId');

        let unsubscribeNews = () => { };
        let unsubscribeLogs = () => { };

        if (selectedProjectId && isProjectRoute) {
            // Fetch project role
            getUserRoleInProject(selectedProjectId, currentUser.uid).then(setProjectRole);

            // Real-time news listener for ALL news
            const newsQuery = query(
                collection(db, "news"),
                where("prjid", "==", selectedProjectId),
                orderBy("createdAt", "desc")
            );
            unsubscribeNews = onSnapshot(newsQuery, { serverTimestamps: 'estimate' }, (snapshot) => {
                const newsItems = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
                const projectSpecificNews = newsItems.filter(item => item.prjid === selectedProjectId);
                setAllNews(projectSpecificNews);
                setNewsIndex(0);
            }, (error) => {
                console.error("Header news listener error:", error);
                setAllNews([]);
            });

        } else {
            setProjectRole(null);
            setLatestNews(null);
            setAllNews([]);
            setNewsIndex(0);
        }

        const logsQuery = query(
            collection(db, "project_logs"),
            orderBy("timestamp", "desc"),
            limit(100)
        );
        
        unsubscribeLogs = onSnapshot(logsQuery, (snapshot) => {
            const currentPid = localStorage.getItem('selectedProjectId');
            const allLogs = snapshot.docs.map(doc => ({ id: doc.id, ...doc.data() }));
            
            if (currentPid && isProjectRoute) {
                const filtered = allLogs.filter(log => log.projId === currentPid);
                setProjectLogs(filtered);
            } else {
                setProjectLogs([]);
            }
        }, (error) => {
            console.error("Header logs listener error:", error);
            setProjectLogs([]);
        });

        return () => {
            unsubscribeInvites();
            unsubscribeNotifs();
            unsubscribeNews();
            unsubscribeLogs();
        };
    }, [currentUser, location.pathname]);

    // Recalculate combined count
    useEffect(() => {
        setNotificationCount(inviteCount + unreadCount);
    }, [inviteCount, unreadCount]);

    // Auto-refresh news ticker rotation
    useEffect(() => {
        if (allNews.length > 1) {
            const interval = setInterval(() => {
                setNewsIndex((prevIndex) => (prevIndex + 1) % allNews.length);
            }, 5000); // Rotate every 5 seconds
            return () => clearInterval(interval);
        } else {
            setNewsIndex(0);
        }
    }, [allNews.length]);

    // Update latest news when index or allNews changes
    useEffect(() => {
        if (allNews.length > 0) {
            setLatestNews(allNews[newsIndex]);
        } else {
            setLatestNews(null);
        }
    }, [newsIndex, allNews]);

    useEffect(() => {
        const handleClickOutside = (event) => {
            if (isProfilePopupOpen && !event.target.closest('.header-profile-section') && !event.target.closest('.profile-dropdown-popup')) {
                setIsProfilePopupOpen(false);
            }
            if (isSearchDropdownOpen && !event.target.closest('.header-search-box')) {
                setIsSearchDropdownOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [isProfilePopupOpen, isSearchDropdownOpen]);

    const handleLogout = async () => {
        try {
            await auth.signOut();
            navigate('/');
        } catch (error) {
            console.error("Logout failed:", error);
        }
    };

    const togglePopup = (e) => {
        e.stopPropagation();
        setIsProfilePopupOpen(!isProfilePopupOpen);
    };

    const openNewsModal = (e) => {
        if (e) e.stopPropagation();
        const selectedProjectId = localStorage.getItem('selectedProjectId');

        if (!selectedProjectId) {
            Swal.fire({
                icon: 'warning',
                title: 'No Project Selected',
                text: 'Please go to a project dashboard first.',
                confirmButtonColor: '#1a4d8c'
            });
            return;
        }

        setIsNewsModalOpen(true);
        // allNews is now handled by the real-time listener in useEffect
    };

    const openHistoryModal = () => {
        setIsHistoryModalOpen(true);
    };

    const handleSearchChange = (e) => {
        const queryStr = e.target.value;
        setSearchQuery(queryStr);

        if (queryStr.trim().length > 0) {
            const filtered = userProjects.filter(p =>
                p.Name.toLowerCase().includes(queryStr.toLowerCase()) ||
                (p.category && p.category.toLowerCase().includes(queryStr.toLowerCase()))
            );
            setFilteredProjects(filtered);
            setIsSearchDropdownOpen(true);
        } else {
            setFilteredProjects([]);
            setIsSearchDropdownOpen(false);
        }
    };

    const handleProjectSelect = (projectId) => {
        localStorage.setItem('selectedProjectId', projectId);
        setIsSearchDropdownOpen(false);
        setSearchQuery('');
        navigate('/project-board');
        // Force a reload if already on project-board to refresh context
        if (window.location.hash.includes('/project-board')) {
            window.location.reload();
        }
    };

    return (
        <>
            <header className="main-header d-flex justify-content-between align-items-center">
                <div className="header-left-group d-flex align-items-center gap-4">
                    <div
                        className="header-profile-section d-flex align-items-center"
                        onClick={togglePopup}
                        style={{ cursor: 'pointer', position: 'relative' }}
                    >
                        {/* CHANGED: Dynamic image source from userData */}
                        {userData.profilePicture ? (
                            <img
                                src={userData.profilePicture}
                                alt="Profile"
                                className="me-2 rounded-circle"
                                style={{ width: '35px', height: '35px', objectFit: 'cover' }}
                            />
                        ) : (
                            <div className="me-2 rounded-circle bg-light d-flex align-items-center justify-content-center" style={{ width: '35px', height: '35px' }}>
                                <UserIcon size={20} color="#878d9fff" />
                            </div>
                        )}

                        <div>
                            <div className="fw-bold small text-nowrap">{userData.fullName}</div>
                            {projectRole && (
                                <div className="small opacity-75" style={{ fontSize: '11px' }}>
                                    {projectRole}
                                </div>
                            )}
                        </div>

                        {isProfilePopupOpen && (
                            <div className="profile-dropdown-popup shadow" onClick={(e) => e.stopPropagation()}>
                                <div className="profile-popup-header d-flex align-items-center mb-3">
                                    {/* CHANGED: Dynamic image in popup */}
                                    {userData.profilePicture ? (
                                        <img
                                            src={userData.profilePicture}
                                            alt="Profile Large"
                                            className="rounded-circle me-3"
                                            style={{ width: '50px', height: '50px', objectFit: 'cover' }}
                                        />
                                    ) : (
                                        <div className="rounded-circle me-3 bg-light d-flex align-items-center justify-content-center" style={{ width: '50px', height: '50px' }}>
                                            <UserIcon size={30} color="#878d9fff" />
                                        </div>
                                    )}
                                    <div className="overflow-hidden">
                                        <div className="fw-bold text-dark text-truncate">{userData.fullName}</div>
                                        <div className="text-muted small text-truncate">{userData.email}</div>
                                    </div>
                                </div>
                                <div className="profile-popup-options">
                                    <button className="popup-option-btn" onClick={() => navigate('/profile')}>
                                        View Profile
                                    </button>
                                    {projectRole !== 'Mentor' && (
                                        <button className="popup-option-btn" onClick={() => navigate('/Mytask')}>
                                            My Tasks
                                        </button>
                                    )}
                                    <button className="popup-option-btn" onClick={() => navigate('/notifications')}>
                                        Notifications
                                    </button>
                                    <button className="popup-option-btn" onClick={() => navigate('/feedback')}>
                                        Feedback
                                    </button>
                                    <hr className="my-2" />
                                    <button className="popup-option-btn logout-btn" onClick={handleLogout}>
                                        Log Out
                                    </button>
                                </div>
                            </div>
                        )}
                    </div>

                    <div className="header-search-box position-relative">
                        <div className="input-group input-group-sm">
                            <span className="input-group-text bg-white border-end-0">
                                <Search size={14} />
                            </span>
                            <input
                                type="text"
                                className="form-control border-start-0 shadow-none"
                                placeholder="Search Projects..."
                                value={searchQuery}
                                onChange={handleSearchChange}
                                onFocus={() => searchQuery.trim() && setIsSearchDropdownOpen(true)}
                            />
                        </div>

                        {isSearchDropdownOpen && filteredProjects.length > 0 && (
                            <div className="search-results-dropdown shadow">
                                {filteredProjects.map(project => (
                                    <div
                                        key={project.proj_id}
                                        className="search-result-item d-flex flex-column"
                                        onClick={() => handleProjectSelect(project.proj_id)}
                                    >
                                        <span className="result-name">{project.Name}</span>
                                        <span className="result-meta">{project.category} • {project.userRole}</span>
                                    </div>
                                ))}
                            </div>
                        )}
                        {isSearchDropdownOpen && searchQuery.trim() && filteredProjects.length === 0 && (
                            <div className="search-results-dropdown shadow p-3 text-center text-muted small">
                                No projects found matching "{searchQuery}"
                            </div>
                        )}
                    </div>

                    {/* Only show news if a project is selected AND we are on a project-specific page */}
                    {localStorage.getItem('selectedProjectId') && ['/project-board', '/mentorDashboard', '/Progress', '/Reviewtask'].includes(location.pathname) && (
                        <div className="header-news-ticker-container d-flex align-items-center gap-2">
                            <div className="header-news-ticker">
                                {latestNews ? (
                                    <div className="ticker-content" key={latestNews.id}>
                                        <span className="ticker-label">LATEST NEWS:</span>
                                        <span className="ticker-message">{latestNews.message}</span>
                                    </div>
                                ) : (
                                    <div className="ticker-content empty" key="empty">
                                        <span className="ticker-message">No news updates yet</span>
                                    </div>
                                )}
                            </div>
                            <button className="view-all-news-btn" onClick={(e) => openNewsModal(e)}>View All</button>
                        </div>
                    )}
                </div>

                <div className="header-actions d-flex align-items-center gap-3">
                    <div style={{ position: 'relative' }}>
                        <Bell
                            size={20}
                            className="header-icon cursor-pointer"
                            title="Notifications"
                            onClick={() => navigate('/notifications')}
                        />
                        {notificationCount > 0 && (
                            <span className="position-absolute top-0 start-100 translate-middle badge rounded-circle bg-danger"
                                style={{ fontSize: '10px', padding: '4px 6px', marginTop: '2px' }}>
                                {notificationCount}
                            </span>
                        )}
                    </div>
                    <History
                        size={20}
                        className="header-icon cursor-pointer"
                        title="Log"
                        onClick={openHistoryModal}
                    />
                </div>
            </header >
            {/* Spacer to prevent content from going under the fixed header */}
            <div style={{ height: '70px' }}></div>

            {
                isNewsModalOpen && (
                    <div className="news-history-modal-overlay">
                        <div className="news-history-modal shadow-lg">
                            <div className="modal-header border-bottom-0 pb-0">
                                <h5 className="fw-bold mb-0">Project News History</h5>
                                <button className="btn-close" onClick={() => setIsNewsModalOpen(false)}></button>
                            </div>
                            <div className="modal-body py-4" style={{ maxHeight: '400px', overflowY: 'auto' }}>
                                {allNews.length > 0 ? (
                                    <div className="news-list">
                                        {allNews.map((news) => (
                                            <div key={news.id} className="news-history-item mb-3 p-3 rounded shadow-sm border">
                                                <div className="d-flex justify-content-between align-items-center mb-2">
                                                    <span className="fw-bold text-primary">{news.senderName || 'Mentor'}</span>
                                                    <small className="text-muted">
                                                        {news.createdAt?.toDate ? news.createdAt.toDate().toLocaleString() : new Date(news.createdAt).toLocaleString()}
                                                    </small>
                                                </div>
                                                <div className="news-message text-dark">
                                                    {news.message}
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="text-center text-muted py-5">
                                        No news history available for this project.
                                    </div>
                                )}
                            </div>
                            <div className="modal-footer border-top-0 pt-0">
                                <button className="btn btn-secondary w-100" style={{ borderRadius: '8px' }} onClick={() => setIsNewsModalOpen(false)}>Close</button>
                            </div>
                        </div>
                    </div>
                )
            }

            {
                isHistoryModalOpen && (
                    <div className="news-history-modal-overlay">
                        <div className="news-history-modal shadow-lg">
                            <div className="modal-header border-bottom-0 pb-0">
                                <h5 className="fw-bold mb-0">Project Activity History</h5>
                                <button className="btn-close" onClick={() => setIsHistoryModalOpen(false)}></button>
                            </div>
                            <div className="modal-body py-4" style={{ maxHeight: '400px', overflowY: 'auto' }}>
                                {projectLogs.length > 0 ? (
                                    <div className="news-list" style={{ padding: '0 10px' }}>
                                        {projectLogs.map((log) => (
                                            <div key={log.id} style={{ marginBottom: '15px', borderBottom: '1px solid #eee', paddingBottom: '10px' }}>
                                                <div style={{ fontSize: '0.9rem' }}>
                                                    <strong>{log.userName}</strong>
                                                    <span style={{ color: '#666', marginLeft: '10px' }}>
                                                        {log.timestamp?.toDate ? log.timestamp.toDate().toLocaleString() : new Date().toLocaleString()}
                                                    </span>
                                                </div>
                                                <div style={{ marginTop: '5px' }}>
                                                    <span style={{ fontSize: '0.85rem', fontWeight: '700', color: '#1a4d8c', letterSpacing: '0.02em' }}>
                                                        {log.actionType}
                                                    </span>
                                                    <div style={{ fontSize: '0.85rem', color: '#555', marginTop: '2px' }}>
                                                        {log.details}
                                                    </div>
                                                </div>
                                            </div>
                                        ))}
                                    </div>
                                ) : (
                                    <div className="text-center text-muted py-5">
                                        No activity history available for this project.
                                    </div>
                                )}
                            </div>
                            <div className="modal-footer border-top-0 pt-0">
                                <button className="btn btn-secondary w-100" style={{ borderRadius: '8px' }} onClick={() => setIsHistoryModalOpen(false)}>Close</button>
                            </div>
                        </div>
                    </div>
                )
            }
        </>
    );
};

export default Header;